// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee, bytes memory _data) public {
        // Restrict to self-call with empty data (guaranteed success in reference)
        vm.assume(callee == address(c));
        vm.assume(_data.length == 0);
        // Call forward; reference never reverts here, mutant may revert
        c.forward(callee, _data);
        // If we reach this point, the call succeeded — the property holds
        assertTrue(true);
    }
}

